    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Cauchy-Schwarz for positive functionals", H("Cauchy-Schwarz for positive functionals"), Blocks(
        Paragraph(Text("For a complex linear functional omega positive on star(a) times a, the squared modulus of omega(star(a) times b) is at most the product of the real values omega(star(a) times a) and omega(star(b) times b). Positivity also gives conjugate symmetry. The quadratic expansion handles the zero diagonal case without division.")),
        Describe.Lean(DescribeId.Create("statement0"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/CauchySchwarz.omega_star_swap_conj"),
            H("omega_star_swap_conj"), StatementSource.FromAuthor(Disp(Statement0())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Positivity makes every diagonal value real. Expanding the positive values at a+b and at i a+b with omega_expand_add and omega_expand_smul_add gives respectively opposite imaginary parts and equal real parts for the two mixed coefficients. These two identities give complex conjugacy, without continuity or normalization."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("statement1"), DeclarationHandle.Create("D5/S3/Quantum/Algebra/StateApproximation/Physicslib4/GNS/CauchySchwarz.cauchy_schwarz_inequality"),
            H("cauchy_schwarz_inequality"), StatementSource.FromAuthor(Disp(Statement1())),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use omega_star_swap_conj and omega_expand_smul_add to write positivity at l a+b as a nonnegative Hermitian quadratic in l. If R=Re omega(a* a) is positive, substitute l=-omega(a* b)/R and rearrange. If R=0, a nonzero mixed coefficient would make this quadratic negative for a sufficiently large negative multiple of that coefficient; hence the mixed coefficient vanishes. This includes the degenerate semidefinite case."))), DescribeRole.Theorem))));

